class CargoManifestEnv:
    """Bin-packing under partial information: minimize bins used within a step budget."""

    N_BOXES = 5
    STEP_LIMIT = 10
    PACK_UNIT_REWARD = 0.1  # 0.1 * 5 boxes = 0.5
    SHIP_OPTIMAL_REWARD = 0.5
    SHIP_NEAR_REWARD = 0.2

    ACTION_RE = re.compile(r'^\s*(INSPECT|PACK|SHIP)\b\s*(.*)$', re.IGNORECASE)

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.box_ids = list(string.ascii_uppercase[: self.N_BOXES])

        # Search for a weight/capacity draw whose optimal bin count is 2 or 3
        # (avoids trivial 1-bin or maximally-fragmented instances).
        for _ in range(200):
            capacity = self.rng.randint(30, 45)
            weights = [self.rng.randint(8, 32) for _ in range(self.N_BOXES)]
            optimal = self._optimal_bins(weights, capacity)
            if optimal is not None and 2 <= optimal <= 3:
                break
        self.capacity = capacity
        self.true_weights = dict(zip(self.box_ids, weights))
        self.optimal_bins = optimal

        self.ranges = {}
        for b in self.box_ids:
            w = self.true_weights[b]
            delta = self.rng.randint(4, 8)
            self.ranges[b] = (max(1, w - delta), w + delta)

        self.inspected = set()
        self.bins = {}  # bin_id (int) -> list of box letters
        self.box_bin = {}  # box letter -> bin_id
        self.steps = 0
        self.done = False

        header = (
            f"CARGO MANIFEST\n"
            f"Ship all {self.N_BOXES} boxes ({', '.join(self.box_ids)}) using as FEW bins as "
            f"possible. Each bin has capacity {self.capacity} kg. Exact box weights are secret; "
            f"you only know rough ranges below. You have {self.STEP_LIMIT} steps total.\n"
            f"Actions (exactly one per turn):\n"
            f"  INSPECT <box>       - reveal a box's exact weight (uses a step)\n"
            f"  PACK <box> <bin#>   - place a box into a numbered bin (bin# is any positive integer)\n"
            f"  SHIP                - finalize once all boxes are packed; ends the episode\n"
        )
        return header + self._status_text(), {"optimal_bins": self.optimal_bins}

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        self.steps += 1
        reward = 0.0
        terminated = False
        msg = ""

        m = self.ACTION_RE.match(action or "")
        if not m:
            msg = "Malformed action. Use 'INSPECT <box>', 'PACK <box> <bin#>', or 'SHIP'."
        else:
            verb = m.group(1).upper()
            rest = m.group(2).strip()

            if verb == "INSPECT":
                box = rest.strip().upper()
                if box not in self.box_ids:
                    msg = f"Unknown box '{rest}'. Valid boxes: {', '.join(self.box_ids)}."
                elif box in self.inspected:
                    msg = f"Box {box} is already inspected: exactly {self.true_weights[box]} kg."
                else:
                    self.inspected.add(box)
                    msg = f"Inspected box {box}: exactly {self.true_weights[box]} kg."

            elif verb == "PACK":
                parts = rest.split()
                if len(parts) != 2 or not parts[1].lstrip('-').isdigit() or int(parts[1]) <= 0:
                    msg = "Use 'PACK <box> <bin#>' with a positive integer bin number."
                else:
                    box = parts[0].strip().upper()
                    bin_id = int(parts[1])
                    if box not in self.box_ids:
                        msg = f"Unknown box '{parts[0]}'. Valid boxes: {', '.join(self.box_ids)}."
                    elif box in self.box_bin:
                        msg = f"Box {box} is already packed in Bin {self.box_bin[box]}."
                    else:
                        load = sum(self.true_weights[x] for x in self.bins.get(bin_id, []))
                        remaining = self.capacity - load
                        w = self.true_weights[box]
                        if w > remaining:
                            msg = (
                                f"Box {box} does NOT fit in Bin {bin_id}: it needs more than the "
                                f"{remaining} kg of space left there (load {load}/{self.capacity})."
                            )
                        else:
                            self.bins.setdefault(bin_id, []).append(box)
                            self.box_bin[box] = bin_id
                            reward = self.PACK_UNIT_REWARD
                            new_load = load + w
                            msg = f"Packed box {box} into Bin {bin_id} (load now {new_load}/{self.capacity})."

            elif verb == "SHIP":
                if len(self.box_bin) < self.N_BOXES:
                    missing = [b for b in self.box_ids if b not in self.box_bin]
                    msg = f"Cannot ship yet: unpacked boxes remain: {', '.join(missing)}."
                else:
                    bins_used = len([bid for bid, items in self.bins.items() if items])
                    terminated = True
                    self.done = True
                    if bins_used == self.optimal_bins:
                        reward = self.SHIP_OPTIMAL_REWARD
                        msg = f"Shipped using {bins_used} bins — optimal! Full ship bonus earned."
                    elif bins_used == self.optimal_bins + 1:
                        reward = self.SHIP_NEAR_REWARD
                        msg = (
                            f"Shipped using {bins_used} bins. A better packing existed "
                            f"({self.optimal_bins} bins was possible). Partial ship bonus earned."
                        )
                    else:
                        msg = (
                            f"Shipped using {bins_used} bins, well above the "
                            f"{self.optimal_bins}-bin optimum. No ship bonus earned."
                        )

        truncated = False
        if not terminated and self.steps >= self.STEP_LIMIT:
            truncated = True
            self.done = True
            msg += " Step limit reached — episode over."

        obs = msg + "\n" + self._status_text()
        return obs, reward, terminated, truncated, {"steps": self.steps}

    def _status_text(self):
        lines = [f"Steps used: {self.steps}/{self.STEP_LIMIT}"]
        if self.bins:
            for bid in sorted(self.bins):
                items = self.bins[bid]
                load = sum(self.true_weights[x] for x in items)
                lines.append(f"  Bin {bid}: [{', '.join(items) if items else '-'}] load {load}/{self.capacity}")
        else:
            lines.append("  No bins opened yet.")
        remaining = [b for b in self.box_ids if b not in self.box_bin]
        if remaining:
            parts = []
            for b in remaining:
                if b in self.inspected:
                    parts.append(f"{b}={self.true_weights[b]}kg")
                else:
                    lo, hi = self.ranges[b]
                    parts.append(f"{b}~{lo}-{hi}kg")
            lines.append("Unpacked: " + ", ".join(parts))
        else:
            lines.append("Unpacked: none — ready to SHIP.")
        return "\n".join(lines)

    @staticmethod
    def _optimal_bins(weights, capacity):
        n = len(weights)
        if any(w > capacity for w in weights):
            return None
        full = (1 << n) - 1
        feasible = [False] * (1 << n)
        for mask in range(1 << n):
            total = sum(weights[i] for i in range(n) if mask & (1 << i))
            feasible[mask] = total <= capacity
        dp = [n + 1] * (1 << n)
        dp[0] = 0
        for mask in range(1, 1 << n):
            sub = mask
            while sub > 0:
                if feasible[sub] and dp[mask ^ sub] + 1 < dp[mask]:
                    dp[mask] = dp[mask ^ sub] + 1
                sub = (sub - 1) & mask
        return dp[full]

import random


class KnaveAmongKnightsEnv:
    NAME_POOL = [
        "Alden", "Brina", "Corwin", "Delia", "Esben",
        "Fenna", "Garrik", "Hesper", "Ilo", "Junne",
    ]
    MAX_STEPS = 10

    def __init__(self):
        self.rng = None
        self.villagers = []
        self.knave = None
        self.cleared = set()
        self.step_count = 0
        self.reward_earned = 0.0
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        n = self.rng.choice([4, 5, 6])
        self.villagers = self.rng.sample(self.NAME_POOL, n)
        self.knave = self.rng.choice(self.villagers)
        self.cleared = set()
        self.step_count = 0
        self.reward_earned = 0.0
        self.done = False

        names_str = ", ".join(self.villagers)
        obs = (
            "You are investigating a village of {n} inhabitants: {names}. "
            "Exactly ONE of them is a knave who always lies; every other "
            "inhabitant is a knight who always tells the truth. Find the "
            "knave.\n\n"
            "Action format (send exactly one per turn):\n"
            "  ASK <name1> <name2>  -- ask <name1> the yes/no question "
            "'Is <name2> a knight?' and receive their answer.\n"
            "  ACCUSE <name>        -- name the villager you believe is the "
            "knave. This ends the game.\n\n"
            "You have at most {steps} turns total, including your final "
            "ACCUSE. Names must be spelled exactly as listed, and <name1> "
            "and <name2> in an ASK must be two different people."
        ).format(n=n, names=names_str, steps=self.MAX_STEPS)
        info = {"villagers": list(self.villagers)}
        return obs, info

    def _find_name(self, token):
        token = token.strip().lower()
        for v in self.villagers:
            if v.lower() == token:
                return v
        return None

    def _check_step_limit(self):
        if self.step_count >= self.MAX_STEPS:
            self.done = True
            return False, True
        return False, False

    def step(self, action):
        if self.done:
            return "The investigation has already ended.", 0.0, True, False, {}

        self.step_count += 1
        action = (action or "").strip()
        parts = action.split()

        if parts and parts[0].upper() == "ACCUSE" and len(parts) == 2:
            target = self._find_name(parts[1])
            if target is None:
                obs = "'{0}' is not a villager in this case. Use one of: {1}.".format(
                    parts[1], ", ".join(self.villagers)
                )
                terminated, truncated = self._check_step_limit()
                return obs, 0.0, terminated, truncated, {}

            self.done = True
            if target == self.knave:
                reward = max(0.0, 1.0 - self.reward_earned)
                self.reward_earned += reward
                obs = "Correct! {0} was the knave. Case closed.".format(target)
                return obs, reward, True, False, {"correct": True}
            else:
                obs = (
                    "Wrong. {0} was not the knave. The real knave slips "
                    "away. Case closed."
                ).format(target)
                return obs, 0.0, True, False, {"correct": False}

        if parts and parts[0].upper() == "ASK" and len(parts) == 3:
            a = self._find_name(parts[1])
            b = self._find_name(parts[2])
            if a is None or b is None:
                bad = parts[1] if a is None else parts[2]
                obs = "'{0}' is not a villager in this case. Use one of: {1}.".format(
                    bad, ", ".join(self.villagers)
                )
                terminated, truncated = self._check_step_limit()
                return obs, 0.0, terminated, truncated, {}
            if a == b:
                obs = "Ask <name1> about a DIFFERENT villager, not themselves."
                terminated, truncated = self._check_step_limit()
                return obs, 0.0, terminated, truncated, {}

            a_is_knave = (a == self.knave)
            b_is_knave = (b == self.knave)
            same_type = (a_is_knave == b_is_knave)

            reward = 0.0
            if same_type:
                newly = [x for x in (a, b) if x not in self.cleared]
                for x in newly:
                    self.cleared.add(x)
                n_possible_knights = len(self.villagers) - 1
                if n_possible_knights > 0 and newly:
                    reward = 0.5 * len(newly) / n_possible_knights
                    self.reward_earned += reward

            obs = "{0} answers your question about {1}: \"{2}.\"".format(
                a, b, "Yes" if same_type else "No"
            )
            terminated, truncated = self._check_step_limit()
            return obs, reward, terminated, truncated, {}

        obs = (
            "Malformed action. Use 'ASK <name1> <name2>' or "
            "'ACCUSE <name>' with names from: {0}."
        ).format(", ".join(self.villagers))
        terminated, truncated = self._check_step_limit()
        return obs, 0.0, terminated, truncated, {}

import random


def _rot_right(s, k):
    k %= len(s)
    return s if k == 0 else s[-k:] + s[:-k]


def _rot_left(s, k):
    k %= len(s)
    return s if k == 0 else s[k:] + s[:k]


def _invert(s):
    return ''.join('.' if c == 'X' else 'X' for c in s)


def _mirror(s):
    return s[::-1]


RULES = {
    'ROTR1': lambda b: _rot_right(b, 1),
    'ROTR2': lambda b: _rot_right(b, 2),
    'ROTL1': lambda b: _rot_left(b, 1),
    'INVERT': _invert,
    'MIRROR': _mirror,
}

RULE_DOC = (
    " ROTR1  - shift every step one position to the right (wrap around)\n"
    " ROTR2  - shift every step two positions to the right (wrap around)\n"
    " ROTL1  - shift every step one position to the left (wrap around)\n"
    " INVERT - flip every hit to a rest and every rest to a hit\n"
    " MIRROR - reverse the order of the 8 steps"
)

L = 8
MASK_SIZE = 3
MAX_STEPS = 10


class DrumPatternContinuationEnv:
    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.steps = 0
        self.bar3_solved = False
        self.bar4_solved = False
        self.rule_solved = False

        hits = self.rng.randint(3, 5)
        positions = set(self.rng.sample(range(L), hits))
        self.bar1 = ''.join('X' if i in positions else '.' for i in range(L))

        self.rule_name = self.rng.choice(list(RULES.keys()))
        rule_fn = RULES[self.rule_name]
        self.bar2 = rule_fn(self.bar1)
        self.bar3 = rule_fn(self.bar2)
        self.bar4 = rule_fn(self.bar3)

        best_mask = None
        for _ in range(20):
            candidate_mask = set(self.rng.sample(range(L), MASK_SIZE))
            revealed = [i for i in range(L) if i not in candidate_mask]
            consistent_count = 0
            for name, fn in RULES.items():
                pred = fn(self.bar1)
                if all(pred[i] == self.bar2[i] for i in revealed):
                    consistent_count += 1
            if best_mask is None:
                best_mask = candidate_mask
            if consistent_count >= 2:
                best_mask = candidate_mask
                break
        self.masked = set(best_mask)

        obs = self._render_intro()
        return obs, {'true_rule': self.rule_name, 'steps': self.steps}

    def _bar2_display(self):
        return ''.join('?' if i in self.masked else self.bar2[i] for i in range(L))

    def _render_intro(self):
        return (
            "You are analyzing a drum rhythm notated in 8 sixteenth-note steps per bar "
            "('X'=hit, '.'=rest; positions 1-8 left to right).\n\n"
            f"Bar 1 (given): {self.bar1}\n"
            f"Bar 2 (partially given): {self._bar2_display()}   ('?' = hidden step)\n\n"
            "A single hidden TRANSFORMATION RULE, drawn from the list below, was applied to "
            "Bar 1 to produce Bar 2, applied again to Bar 2 to produce Bar 3, and again to "
            "Bar 3 to produce Bar 4. Your job is to identify the rule and predict Bars 3 and 4 exactly.\n\n"
            "Candidate rules:\n" + RULE_DOC + "\n\n"
            f"You have up to {MAX_STEPS} actions total. Send exactly one action per turn:\n"
            " TEST <RULE_NAME>          - check how many currently visible Bar 2 steps a candidate rule matches (no reward, information only)\n"
            " REVEAL <position 1-8>     - reveal one currently hidden ('?') step of Bar 2\n"
            " SUBMIT_RULE <RULE_NAME>   - claim the true rule (reward 0.3 the first time you are correct)\n"
            " GUESS <bar3> <bar4>       - state your full 8-character prediction for Bar 3 and Bar 4, "
            "e.g. GUESS X..X.X.. .X..X..X (reward 0.3 for an exact Bar 3, 0.4 for an exact Bar 4, first "
            "time each; episode succeeds once both are exact)\n\n"
            "Malformed actions cost a step and get a corrective message but no reward."
        )

    def step(self, action):
        self.steps += 1
        info = {'steps': self.steps}
        reward = 0.0
        terminated = False

        tokens = (action or '').strip().split()
        if not tokens:
            obs = "Empty action. Use TEST, REVEAL, SUBMIT_RULE, or GUESS as described."
            return obs, reward, terminated, self._check_truncate(), info

        cmd = tokens[0].upper()

        if cmd == 'TEST' and len(tokens) == 2:
            name = tokens[1].upper()
            if name not in RULES:
                obs = f"Unknown rule name '{tokens[1]}'. Valid names: {', '.join(RULES)}."
            else:
                pred = RULES[name](self.bar1)
                revealed = [i for i in range(L) if i not in self.masked]
                matches = sum(1 for i in revealed if pred[i] == self.bar2[i])
                total = len(revealed)
                consistent = "consistent with all visible steps" if matches == total else "NOT fully consistent"
                obs = (f"TEST {name}: matches {matches}/{total} visible Bar 2 steps ({consistent})."
                       f"\nBar 2 so far: {self._bar2_display()}")

        elif cmd == 'REVEAL' and len(tokens) == 2:
            try:
                pos = int(tokens[1])
            except ValueError:
                pos = None
            if pos is None or pos < 1 or pos > L:
                obs = f"Invalid position '{tokens[1]}'. Use REVEAL <position 1-8>."
            elif (pos - 1) not in self.masked:
                obs = f"Step {pos} is already visible: {self._bar2_display()}"
            else:
                self.masked.discard(pos - 1)
                obs = f"Revealed step {pos} of Bar 2. Bar 2 so far: {self._bar2_display()}"

        elif cmd == 'SUBMIT_RULE' and len(tokens) == 2:
            name = tokens[1].upper()
            if name not in RULES:
                obs = f"Unknown rule name '{tokens[1]}'. Valid names: {', '.join(RULES)}."
            elif name == self.rule_name:
                if not self.rule_solved:
                    self.rule_solved = True
                    reward += 0.3
                    obs = f"Correct! {name} is the hidden rule. (+0.3)"
                else:
                    obs = f"Correct, {name} is the hidden rule (already credited)."
            else:
                obs = f"{name} is not the hidden rule."

        elif cmd == 'GUESS' and len(tokens) == 3:
            g3, g4 = tokens[1].upper(), tokens[2].upper()
            valid3 = len(g3) == L and set(g3) <= {'X', '.'}
            valid4 = len(g4) == L and set(g4) <= {'X', '.'}
            if not (valid3 and valid4):
                obs = "Each guess must be an 8-character string of only 'X' and '.'. Format: GUESS <bar3> <bar4>."
            else:
                match3 = sum(1 for i in range(L) if g3[i] == self.bar3[i])
                match4 = sum(1 for i in range(L) if g4[i] == self.bar4[i])
                lines = [f"Bar 3 guess matched {match3}/{L} steps.", f"Bar 4 guess matched {match4}/{L} steps."]
                if match3 == L and not self.bar3_solved:
                    self.bar3_solved = True
                    reward += 0.3
                    lines.append("Bar 3 is exactly correct! (+0.3)")
                if match4 == L and not self.bar4_solved:
                    self.bar4_solved = True
                    reward += 0.4
                    lines.append("Bar 4 is exactly correct! (+0.4)")
                if self.bar3_solved and self.bar4_solved:
                    terminated = True
                    lines.append("Both bars confirmed exact. Episode complete.")
                obs = "\n".join(lines)

        else:
            obs = ("Unrecognized action. Use one of:\n"
                   " TEST <RULE_NAME>\n REVEAL <position 1-8>\n SUBMIT_RULE <RULE_NAME>\n GUESS <bar3> <bar4>")

        truncated = self._check_truncate() and not terminated
        reward = max(0.0, min(1.0, reward))
        return obs, reward, terminated, truncated, info

    def _check_truncate(self):
        return self.steps >= MAX_STEPS

