import re


class FestivalCycleEnv:
    """Infer a hidden repeating festival pattern over a calendar, then
    predict festival days in an unseen future window."""

    PROBE_LO, PROBE_HI = 1, 40
    TARGET_LO, TARGET_HI = 41, 60
    MAX_STEPS = 10

    def __init__(self):
        self.rng = None
        self.period = None
        self.offsets = None
        self.step_count = 0
        self.period_guessed = False
        self.done = False

    def _is_festival(self, day):
        return ((day - 1) % self.period) in self.offsets

    def _true_target_set(self):
        return {d for d in range(self.TARGET_LO, self.TARGET_HI + 1)
                if self._is_festival(d)}

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.period = self.rng.randint(3, 7)
        k = self.rng.randint(1, min(3, self.period - 1) if self.period > 1 else 1)
        self.offsets = set(self.rng.sample(range(self.period), k))
        self.step_count = 0
        self.period_guessed = False
        self.done = False

        obs = (
            "FESTIVAL CALENDAR PATTERN. A repeating festival cycle governs "
            f"days 1-{self.TARGET_HI} of an ancient calendar; you cannot see "
            "the rule directly.\n"
            f"You have {self.MAX_STEPS} actions total. Available actions:\n"
            f"  CHECK <day>      - reveals whether <day> (an integer in "
            f"{self.PROBE_LO}-{self.PROBE_HI}) is a festival day.\n"
            "  PERIOD <n>       - one-time guess at the cycle's repeat "
            "length; correct guess earns 0.3 reward.\n"
            f"  PREDICT <d1,d2,...> - final action, ends the episode. List "
            f"every day in {self.TARGET_LO}-{self.TARGET_HI} you believe is "
            "a festival day; an exact match earns 0.7, partial matches earn "
            "partial credit.\n"
            "Malformed actions cost a step but earn no reward."
        )
        return obs, {}

    def step(self, action):
        if self.done:
            return "Episode already ended.", 0.0, True, False, {}

        self.step_count += 1
        action = (action or "").strip()

        m = re.fullmatch(r'CHECK\s+(-?\d+)', action, re.IGNORECASE)
        if m:
            day = int(m.group(1))
            if not (self.PROBE_LO <= day <= self.PROBE_HI):
                obs = (
                    f"Malformed CHECK: day must be between {self.PROBE_LO} "
                    f"and {self.PROBE_HI}."
                )
                return self._finish(obs, 0.0)
            fest = self._is_festival(day)
            obs = f"Day {day}: {'FESTIVAL' if fest else 'ordinary day'}."
            return self._finish(obs, 0.0)

        m = re.fullmatch(r'PERIOD\s+(-?\d+)', action, re.IGNORECASE)
        if m:
            if self.period_guessed:
                obs = "You already used your one-time period guess."
                return self._finish(obs, 0.0)
            self.period_guessed = True
            guess = int(m.group(1))
            if guess == self.period:
                obs = "Correct: that is the cycle's repeat length."
                return self._finish(obs, 0.3)
            obs = "Incorrect period guess. No further period guesses remain."
            return self._finish(obs, 0.0)

        m = re.fullmatch(r'PREDICT\s+(.*)', action, re.IGNORECASE)
        if m:
            raw = m.group(1)
            nums = re.findall(r'-?\d+', raw)
            predicted = {int(n) for n in nums}
            true_set = self._true_target_set()
            union = predicted | true_set
            if not union:
                jaccard = 1.0
            else:
                jaccard = len(predicted & true_set) / len(union)
            reward = 0.7 if predicted == true_set else 0.7 * jaccard
            obs = (
                f"PREDICT submitted: {sorted(predicted)}. True festival days "
                f"in {self.TARGET_LO}-{self.TARGET_HI}: {sorted(true_set)}. "
                f"Match score: {jaccard:.2f}."
            )
            self.done = True
            return obs, reward, True, False, {}

        obs = (
            "Malformed action. Use 'CHECK <day>', 'PERIOD <n>', or "
            "'PREDICT <d1,d2,...>'."
        )
        return self._finish(obs, 0.0)

    def _finish(self, obs, reward):
        if self.step_count >= self.MAX_STEPS:
            self.done = True
            obs += " Step limit reached; episode truncated without a PREDICT."
            return obs, reward, False, True, {}
        return obs, reward, False, False, {}

import random


class SymmetryDetectiveEnv:
    ALPHABET = ['A', 'B', 'C', 'D']
    MAX_STEPS = 10

    def __init__(self):
        self.rng = None
        self.map = {}
        self.targets = []
        self.target_labels = []
        self.steps = 0
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.steps = 0
        self.done = False

        unassigned = list(self.ALPHABET)
        self.map = {}
        while unassigned:
            x = unassigned.pop(0)
            if unassigned and self.rng.random() < 0.6:
                y = self.rng.choice(unassigned)
                unassigned.remove(y)
                self.map[x] = y
                self.map[y] = x
            else:
                self.map[x] = x

        labels = [True, True, False, False]
        self.rng.shuffle(labels)
        self.targets = [self._make_string(lbl) for lbl in labels]
        self.target_labels = labels

        obs = self._format_intro()
        return obs, {}

    def _make_string(self, symmetric):
        s = [None] * 6
        for i in range(3):
            letter = self.rng.choice(self.ALPHABET)
            s[i] = letter
            s[5 - i] = self.map[letter]
        if not symmetric:
            idx = self.rng.choice([0, 1, 2])
            correct = self.map[s[idx]]
            choices = [c for c in self.ALPHABET if c != correct]
            s[5 - idx] = self.rng.choice(choices)
        return ''.join(s)

    def _format_intro(self):
        lines = []
        lines.append("SYMMETRY DETECTIVE")
        lines.append(
            "A secret 180-degree rotation rule maps each letter in {A,B,C,D} to "
            "another letter (or itself); it is an involution (apply it twice, "
            "get the original letter back)."
        )
        lines.append(
            "A length-6 string is ROTATION-SYMMETRIC if, for each mirrored "
            "position pair (0,5), (1,4), (2,3), the rule applied to the left "
            "letter equals the right letter."
        )
        lines.append("Classify these 4 target strings as symmetric (T) or not (F):")
        for i, t in enumerate(self.targets, 1):
            lines.append(f"  {i}: {t}")
        lines.append(f"You have {self.MAX_STEPS} steps total. Actions:")
        lines.append(
            "  EXAMPLE <string>  - a length-6 string of letters A-D; returns "
            "MATCH/MISMATCH for each of the 3 mirrored position-pairs."
        )
        lines.append(
            "  CLASSIFY <T/F> <T/F> <T/F> <T/F>  - final answer for targets "
            "1-4 in order. Ends the episode; scores 0.25 per correct answer."
        )
        lines.append("Use EXAMPLE to gather evidence before you CLASSIFY.")
        return "\n".join(lines)

    def step(self, action):
        if self.done:
            return ("Episode already finished.", 0.0, True, False, {})

        self.steps += 1
        tokens = str(action).strip().split()
        reward = 0.0
        terminated = False
        obs = ""

        if not tokens:
            obs = "Empty action. Use EXAMPLE <string> or CLASSIFY <T/F> <T/F> <T/F> <T/F>."
        else:
            cmd = tokens[0].upper()

            if cmd == "EXAMPLE":
                if len(tokens) != 2 or len(tokens[1]) != 6 or \
                        not all(c.upper() in self.ALPHABET for c in tokens[1]):
                    obs = (
                        "Malformed EXAMPLE. Provide exactly one string of length 6 "
                        "using only letters A, B, C, D. Example: EXAMPLE AABBCD"
                    )
                else:
                    s = tokens[1].upper()
                    lines = [f"Feedback for EXAMPLE {s}:"]
                    for i in range(3):
                        a, b = s[i], s[5 - i]
                        match = self.map[a] == b
                        lines.append(
                            f"  pair({i},{5 - i}) [{a},{b}]: "
                            f"{'MATCH' if match else 'MISMATCH'}"
                        )
                    obs = "\n".join(lines)

            elif cmd == "CLASSIFY":
                valid = len(tokens) == 5 and all(
                    t.upper() in ("T", "F") for t in tokens[1:]
                )
                if not valid:
                    obs = (
                        "Malformed CLASSIFY. Provide exactly 4 answers, each T or F, "
                        "e.g.: CLASSIFY T F T F"
                    )
                else:
                    answers = [t.upper() == "T" for t in tokens[1:5]]
                    correct = sum(
                        1 for a, b in zip(answers, self.target_labels) if a == b
                    )
                    reward = 0.25 * correct
                    terminated = True
                    self.done = True
                    lines = [
                        f"CLASSIFY submitted: {correct}/4 correct.",
                        "True labels: " + ", ".join(
                            "T" if lbl else "F" for lbl in self.target_labels
                        ),
                        "Secret rule: " + ", ".join(
                            f"{k}->{v}" for k, v in sorted(self.map.items())
                        ),
                    ]
                    obs = "\n".join(lines)

            else:
                obs = (
                    f"Unknown command '{tokens[0]}'. Use EXAMPLE or CLASSIFY."
                )

        truncated = (not terminated) and (self.steps >= self.MAX_STEPS)
        if truncated:
            self.done = True
            obs += "\nStep limit reached. Episode truncated."

        return obs, reward, terminated, truncated, {}
